//! The stores of the frame allocator's users into memory it handed out (generated by the
//! heap-hooks site generator from game_scarlett_master.exe 1.0.2.1; do not edit by hand). Every
//! store found through the bump-run head tables (0x9ab3b80, 0x9ab3bb0, 0x9ab3be0, 0x9ab3c10,
//! 0x91ac980, 0x9188c70), the allocator calls, the reserve's return value (0x517a290), the
//! title's thread-locals that point into frame memory, and the objects of writers the guard
//! named in live runs, grouped into spans of whole instructions with no branch target inside;
//! the flag set where a hooked store's flags are read before they are set again.
//!
//! The title's bytes are not here. A row names its window by its offset in the image, its length
//! and its BLAKE3-64 (the low eight bytes of its BLAKE3-256 digest, little-endian), and says what
//! to make of it: an instruction recipe from [`RECIPES`], where the patched span starts in it,
//! whether the flags live after the span, and which list of the title's TLS-array loads in the
//! window [`TLS`] holds (`crate::tls` may have turned those into calls of their thunk, which is
//! still the title's code: see `heap_sites::Site::window`). `apply` takes the window's bytes from
//! the mapped image once they are the recorded ones, and nothing is written when they are not:
//! another build of the title is refused, site by site, with the tag it found.

use super::{Insn, Note, Site, Tls};

/// A hooked store's note in these rows: every one of them writes bytes that are no
/// descriptor record but the frame allocator's own lists. (Records come from the table
/// fillers and the sites of `OWN`, which name their notes themselves.)
const O: Note = Note::Other;

/// A store of `n` bytes, a span left as it is, and one whose displacement at `.1` moves with
/// it. One letter each, and uppercase, to keep the table below short: they are marks between the
/// offsets of a span, not names to read.
#[allow(non_snake_case)]
const fn S(n: u8, note: Note) -> Insn {
    Insn::Store(n as usize, note)
}

#[allow(non_snake_case)]
const fn P(n: u8) -> Insn {
    Insn::Plain(n as usize)
}

#[allow(non_snake_case)]
const fn Q(n: u8, disp: u8) -> Insn {
    Insn::Relative(n as usize, disp as usize)
}

