/// The sites [`super::sites`] adds: these rows, in the order the generator found them. A row's
/// name says only what these stores are; `apply` names a site with its window, which is what
/// distinguishes them.
pub(super) fn sites() -> Vec<Site> {
    ROWS.iter()
        .map(|&(window, len, digest, recipe, span, flags_live, tls)| Site {
            name: "frame user",
            window: window as usize,
            len,
            digest,
            tls: TLS[usize::from(tls)],
            span: usize::from(span),
            insns: RECIPES[usize::from(recipe)],
            flags_live,
        })
        .collect()
}
